bool LampStage::Resize(uint32_t w,uint32_t h,uint32_t scale){if(!gpu_||!w||!h||scale<1||scale>4)return false;Shutdown();width_=w;height_=h;scale_=scale;bool ok=gpu_->Create(table_,Source::kLampSlots,Source::kLampTableRows,VK_FORMAT_R32G32B32A32_SFLOAT)&&gpu_->Create(tiles_,((w+63)/64)*16,((h+63)/64)*8*2,VK_FORMAT_R8_UNORM)&&gpu_->Create(visibility_[0],Source::kLampSlots,1,VK_FORMAT_R16G16B16A16_SFLOAT)&&gpu_->Create(visibility_[1],Source::kLampSlots,1,VK_FORMAT_R16G16B16A16_SFLOAT)&&gpu_->Create(surfaces_,w,h,VK_FORMAT_R16G16B16A16_SFLOAT)&&gpu_->Create(blur_,w,h,VK_FORMAT_R16G16B16A16_SFLOAT)&&gpu_->Create(halos_,(w+scale-1)/scale,(h+scale-1)/scale,VK_FORMAT_R16G16B16A16_SFLOAT);if(!ok)Shutdown();return ok;}
bool LampStage::Record(const Uniforms&common,const Source::LampTable&table,const Source::LampTiles&tiles,Texture depth,Texture fog,Texture occluder,float blend,const std::array<float,4>&sun,const Source::CarrierBody&body,bool surfaces,bool halos,bool useTiles){if(!gpu_||!table_.handle||!depth.view||table.slots<0||table.slots>Source::kLampSlots||tiles.TextureWidth()!=tiles_.extent.width||tiles.TextureHeight()!=tiles_.extent.height)return false;
 if(!gpu_->Upload(table_,table.texels,sizeof table.texels)||!gpu_->Upload(tiles_,tiles.Texels().data(),tiles.Texels().size()))return false;
 if(!valid_)for(auto&v:visibility_)if(!gpu_->Clear(v,{1,1,1,1}))return false;
 std::array<Texture,16>t{};t[0]=depth;t[1]=gpu_->Sample(visibility_[ping_]);t[2]=gpu_->Sample(table_);auto u=common;u.r[9]={valid_?blend:1,0,0,0};unsigned next=1-ping_;if(!gpu_->Run(Kernel::LampVisibility,u,t,visibility_[next]))return false;ping_=next;valid_=true;
 if(surfaces){t={};t[0]=depth;t[1]=gpu_->Sample(table_);t[2]=occluder.view?occluder:depth;t[3]=gpu_->Sample(tiles_);u=common;u.r[1][0]=1;u.r[8]={float(width_),float(height_),1.f/width_,1.f/height_};u.r[9]={float(table.surfaceSlots),0,0,0};u.r[10]=sun;u.r[11]={body.base[0],body.base[1],body.base[2],body.radius};u.r[12]={body.up[0],body.up[1],body.up[2],body.height};u.r[13]={1.f/tiles_.extent.width,1.f/tiles_.extent.height,0,useTiles?64.f:0};if(!gpu_->Run(Kernel::LampSurfaces,u,t,surfaces_))return false;}else if(!gpu_->Clear(surfaces_,{0,0,0,0}))return false;
 if(halos){t={};t[0]=depth;t[1]=fog;t[2]=gpu_->Sample(visibility_[ping_]);t[3]=gpu_->Sample(table_);t[4]=gpu_->Sample(tiles_);u=common;u.r[1][0]=float(scale_);u.r[8]={float(halos_.extent.width),float(halos_.extent.height),1.f/halos_.extent.width,1.f/halos_.extent.height};u.r[9][0]=float(table.slots);u.r[10]={1.f/tiles_.extent.width,1.f/tiles_.extent.height,float(tiles.TilesY()*8),useTiles?64.f:0};if(!gpu_->Run(Kernel::LampHalos,u,t,halos_))return false;}else if(!gpu_->Clear(halos_,{0,0,0,0}))return false;return true;
}

bool LampStage::UploadTable(const Source::LampTable&t,const Source::LampTiles&tiles){if(!gpu_||!table_.handle||tiles.TextureWidth()!=tiles_.extent.width||tiles.TextureHeight()!=tiles_.extent.height||t.slots<0||t.slots>Source::kLampSlots||t.surfaceSlots<0||t.surfaceSlots>Source::kSurfaceSlots)return false;surfaceSlots_=t.surfaceSlots;slots_=t.slots;return gpu_->Upload(table_,t.texels,sizeof t.texels)&&gpu_->Upload(tiles_,tiles.Texels().data(),tiles.Texels().size());}
bool LampStage::RecordSurfaces(const Uniforms&common,Texture depth,Texture occ,const std::array<float,4>&sun,const Source::CarrierBody&body,bool blur,bool tiles,Texture material,Texture normals){if(!gpu_||!surfaces_.handle||!depth.view)return false;auto u=common;u.r[1][0]=1;u.r[8]={float(width_),float(height_),1.f/width_,1.f/height_};u.r[9]={float(surfaceSlots_),0,0,0};u.r[10]=sun;u.r[11]={body.base[0],body.base[1],body.base[2],body.radius};u.r[12]={body.up[0],body.up[1],body.up[2],body.height};u.r[13]={1.f/tiles_.extent.width,1.f/tiles_.extent.height,0,tiles?64.f:0};std::array<Texture,16>t{};t[0]=depth;t[1]=gpu_->Sample(table_);t[2]=occ.view?occ:depth;t[3]=gpu_->Sample(tiles_);t[4]=material;t[5]=normals;u.r[14]={normals.view?1.f:0.f,0,0,0};if(!gpu_->Run(Kernel::LampSurfaces,u,t,surfaces_))return false;if(blur){t={};t[0]=depth;t[1]=gpu_->Sample(surfaces_);u.r[9]={1,0,0,0};if(!gpu_->Run(Kernel::LampBlur,u,t,blur_))return false;t[1]=gpu_->Sample(blur_);u.r[9]={0,1,0,0};if(!gpu_->Run(Kernel::LampBlur,u,t,surfaces_))return false;}return true;}
bool LampStage::RecordHalos(const Uniforms&common,Texture depth,Texture fog,float blend,bool transmittance,bool tiles,std::array<float,4> fogUV){if(!gpu_||!halos_.handle||!depth.view||!fog.view)return false;if(!valid_)for(auto&v:visibility_)if(!gpu_->Clear(v,{1,1,1,1}))return false;auto u=common;std::array<Texture,16>t{};t[0]=depth;t[1]=gpu_->Sample(visibility_[ping_]);t[2]=gpu_->Sample(table_);u.r[9]={valid_?blend:1,0,0,0};unsigned next=1-ping_;if(!gpu_->Run(Kernel::LampVisibility,u,t,visibility_[next]))return false;ping_=next;valid_=true;u=common;u.r[1][0]=float(scale_);u.r[8]={float(halos_.extent.width),float(halos_.extent.height),1.f/halos_.extent.width,1.f/halos_.extent.height};u.r[9][0]=float(slots_);u.r[10]={1.f/tiles_.extent.width,1.f/tiles_.extent.height,float(((height_+63)/64)*8),tiles?64.f:0};u.r[11]={transmittance?1.f:0.f,0,0,0};u.r[12]=fogUV;t={};t[0]=depth;t[1]=fog;t[2]=gpu_->Sample(visibility_[ping_]);t[3]=gpu_->Sample(table_);t[4]=gpu_->Sample(tiles_);return gpu_->Run(Kernel::LampHalos,u,t,halos_);}
void LampStage::Shutdown(){if(!gpu_)return;for(auto*t:{&table_,&tiles_,&visibility_[0],&visibility_[1],&surfaces_,&halos_,&blur_})gpu_->Retire(*t);ping_=0;valid_=false;}
bool FogStage::Resize(uint32_t w,uint32_t h,uint32_t scale){if(!gpu_||!w||!h||scale<1||scale>4)return false;Shutdown();w=(w+scale-1)/scale;h=(h+scale-1)/scale;bool ok=gpu_->Create(current_,w,h,VK_FORMAT_R16G16B16A16_SFLOAT)&&gpu_->Create(history_[0],w,h,VK_FORMAT_R16G16B16A16_SFLOAT)&&gpu_->Create(history_[1],w,h,VK_FORMAT_R16G16B16A16_SFLOAT);if(!ok)Shutdown();return ok;}
bool FogStage::Record(const Uniforms&march,const Uniforms&temporal,const std::array<Texture,16>&inputs,unsigned quality,bool memory,bool reset){if(!gpu_||!current_.handle||!inputs[0].view||!inputs[1].view||quality<1||quality>3)return false;if(memory&&(!inputs[3].view||!inputs[4].view))return false;if(!valid_||reset)for(auto&t:history_)if(!gpu_->Clear(t,{0,0,0,0}))return false;
 auto kernel=Kernel(unsigned(Kernel::Fog1Memory0)+(quality-1)*2+(memory?1:0));if(!gpu_->Run(kernel,march,inputs,current_))return false;auto u=temporal;u.r[13][1]=valid_&&!reset?1.f:0.f;std::array<Texture,16>t{};t[0]=gpu_->Sample(current_);t[1]=gpu_->Sample(history_[ping_]);t[2]=inputs[0];auto next=1-ping_;if(!gpu_->Run(Kernel::FogTemporal,u,t,history_[next]))return false;ping_=next;valid_=true;return true;}
void FogStage::Shutdown(){if(!gpu_)return;for(auto*t:{&current_,&history_[0],&history_[1]})gpu_->Retire(*t);ping_=0;valid_=false;}
bool SpellStage::Resize(uint32_t w,uint32_t h){if(!gpu_||!w||!h)return false;Shutdown();width_=w;height_=h;auto gw=(w+7)/8,gh=(h+7)/8;columns_=(gw+3)/4;rows_=(gh+3)/4;bool ok=gpu_->Create(gatherLight_,gw,gh,VK_FORMAT_R32G32B32A32_SFLOAT)&&gpu_->Create(gatherPlace_,gw,gh,VK_FORMAT_R32G32B32A32_SFLOAT)&&gpu_->Create(reduced_,2*columns_,rows_,VK_FORMAT_R32G32B32A32_SFLOAT);if(!ok)Shutdown();return ok;}
bool SpellStage::Record(const Uniforms&common,Texture before,Texture now,Texture beforeDepth,Texture nowDepth,bool swapRB){if(!gpu_||!reduced_.handle||!before.view||!now.view||!beforeDepth.view||!nowDepth.view)return false;std::array<Texture,16>t{};t[0]=now;t[1]=before;t[2]=beforeDepth;t[3]=nowDepth;auto u=common;u.r[9]={Source::kEffectThreshold,Source::kEffectNearestYards,Source::kEffectFarthestYards,Source::kEffectDepthChange};u.r[10]={1.f/width_,1.f/height_,1.f/64,0};u.r[11]={swapRB?1.f:0.f,0,0,0};if(!gpu_->Run(Kernel::EffectGather,u,t,gatherLight_,&gatherPlace_))return false;t={};t[0]=gpu_->Sample(gatherLight_);t[1]=gpu_->Sample(gatherPlace_);u.r[9]={float(columns_),1.f/16,0,0};u.r[10]={float(gatherLight_.extent.width),float(gatherLight_.extent.height),1.f/gatherLight_.extent.width,1.f/gatherLight_.extent.height};return gpu_->Run(Kernel::EffectReduce,u,t,reduced_);}
void SpellStage::Shutdown(){if(!gpu_)return;for(auto*t:{&gatherLight_,&gatherPlace_,&reduced_})gpu_->Retire(*t);}
